function Draft({
  message,
  onSave,
  onQueue,
  busy,
}: {
  message: Message;
  onSave: (content: string) => void;
  onQueue: () => void;
  busy: boolean;
}) {
  const [content, setContent] = useState(message.content);
  useEffect(() => setContent(message.content), [message.content]);
  return (
    <div className="draft">
      <div className="section-head">
        <strong>
          {message.kind === "invitation" ? "Invitation" : "Suivi"} Â·{" "}
          {message.state === "sent" ? "EnvoyÃ©" : "Brouillon"}
        </strong>
        <small>
          {message.sentAt
            ? dateTime(message.sentAt)
            : dateTime(message.createdAt)}
        </small>
      </div>
      <textarea
        rows={5}
        value={content}
        disabled={message.state === "sent"}
        onChange={(e) => setContent(e.target.value)}
      />
      {message.state === "draft" && (
        <div className="button-row">
          <button
            className="secondary small"
            disabled={busy || content === message.content}
            onClick={() => onSave(content)}
          >
            Enregistrer le texte
          </button>
          <button
            className="primary small"
            disabled={busy || content !== message.content}
            onClick={onQueue}
          >
            Placer dans la file â†’
          </button>
        </div>
      )}
    </div>
  );
}
function Empty({
  icon,
  title,
  body,
}: {
  icon: string;
  title: string;
  body: string;
}) {
  return (
    <div className="empty">
      <span>{icon}</span>
      <strong>{title}</strong>
      <p>{body}</p>
    </div>
  );
}
